css:
.loader {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid #6366f1;
  box-sizing: border-box;
  background-color: #eef2ff;
  background-image:
    radial-gradient(circle at 50% 50%, #6366f1 18%, transparent 19%),
    radial-gradient(circle at 20% 30%, #6366f1 8%, transparent 9%),
    radial-gradient(circle at 80% 30%, #6366f1 8%, transparent 9%),
    radial-gradient(circle at 25% 80%, #6366f1 8%, transparent 9%),
    radial-gradient(circle at 75% 80%, #6366f1 8%, transparent 9%);
  animation: spin 1s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }
